cssVarsTemplate:
@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  :root {
    --background: 0 0% 100%;
    --foreground: 210 68% 20%;
    --card: 0 0% 100%;
    --card-foreground: 210 68% 20%;
    --popover: 0 0% 100%;
    --popover-foreground: 210 68% 20%;
    --primary: 210 66% 31%;
    --primary-foreground: 210 100% 97%;
    --secondary: 210 100% 91%;
    --secondary-foreground: 210 66% 31%;
    --muted: 210 100% 91%;
    --muted-foreground: 210 94% 58%;
    --accent: 210 100% 91%;
    --accent-foreground: 210 66% 31%;
    --destructive: 10 85% 58%;
    --destructive-foreground: 210 100% 97%;
    --border: 210 100% 85%;
    --input: 210 100% 85%;
    --ring: 210 68% 20%;
    --radius: 0.5rem;
    --chart-1: 12 76% 61%;
    --chart-2: 173 58% 39%;
    --chart-3: 197 37% 24%;
    --chart-4: 43 74% 66%;
    --chart-5: 27 87% 67%;
  }

  .dark {
    --background: 210 68% 20%;
    --foreground: 210 100% 97%;
    --card: 210 68% 20%;
    --card-foreground: 210 100% 97%;
    --popover: 210 68% 20%;
    --popover-foreground: 210 100% 97%;
    --primary: 210 100% 97%;
    --primary-foreground: 210 66% 31%;
    --secondary: 210 76% 37%;
    --secondary-foreground: 210 100% 97%;
    --muted: 210 76% 37%;
    --muted-foreground: 210 96% 66%;
    --accent: 210 76% 37%;
    --accent-foreground: 210 100% 97%;
    --destructive: 10 63% 29%;
    --destructive-foreground: 210 100% 97%;
    --border: 210 76% 37%;
    --input: 210 76% 37%;
    --ring: 210 100% 76%;
    --chart-1: 220 70% 50%;
    --chart-2: 160 60% 45%;
    --chart-3: 30 80% 55%;
    --chart-4: 280 65% 60%;
    --chart-5: 340 75% 55%;
  }
}

@layer base {
  * {
    @apply border-border;
  }
  body {
    @apply bg-background text-foreground;
  }
}
